import { immer } from "zustand/middleware/immer";
import { checkIsMembership, userPublicLocalStorage } from "../user";
import { shallow } from 'zustand/shallow';
import { createWithEqualityFn } from 'zustand/traditional';
import { subscribeWithSelector } from 'zustand/middleware';
import { v4 as uuidv4 } from 'uuid';
import throttle from 'lodash-es/throttle';
import { recordDebugLog } from "../../utils/helpers";

export const snapshotCacheInstance = async () => {
    return await userPublicLocalStorage('snapshots');
};

const getMaxAutoCreateSnapshotCount = async () => {
    const isMember = await checkIsMembership();
    return isMember ? 5 : 3;
}

const getTabUrlKey = (tab) => {
    try {
        const url = new URL(tab.url);
        return `${url.origin}${url.pathname}`;
    } catch {
        return tab.url;
    }
};

const compareWindows = (windows1, windows2) => {
    if (!windows1 || !windows2 || windows1.length !== windows2.length) return false;

    for (let i = 0; i < windows1.length; i++) {
        const tabs1 = windows1[i]?.tabs;
        const tabs2 = windows2[i]?.tabs;

        if (!tabs1 || !tabs2 || tabs1.length !== tabs2.length) return false;

        const urls1 = tabs1.map(getTabUrlKey).sort();
        const urls2 = tabs2.map(getTabUrlKey).sort();

        for (let j = 0; j < urls1.length; j++) {
            if (urls1[j] !== urls2[j]) return false;
        }
    }

    return true;
};

export const snapshotStore = createWithEqualityFn(subscribeWithSelector(immer((set, get) => ({
    summaries: [],
    snapshotDetails: {},
    selectedSnapshotId: null,
    selectedTabs: {},
    selectedGroups: {},

    fetchSummaries: async () => {
        try {
            const cacheInstance = await snapshotCacheInstance();
            const keys = await cacheInstance.keys();
            const summaries = await Promise.all(
                keys.filter(key => key.startsWith('snapshot_summary_'))
                    .map(key => cacheInstance.get(key))
            );
            set({ summaries: summaries.filter(Boolean) });
        } catch (error) {
            console.error('Error fetching summaries:', error);
            set({ summaries: [] });
        }
    },

    fetchSnapshot: async (id) => {
        if (!id) return null;
        const cacheInstance = await snapshotCacheInstance();
        return await cacheInstance.get(`snapshot_detail_${id}`);
    },

    addSnapshot: async (cached = null, isAutoCreated = false) => {
        try {
            const id = uuidv4();
            let windows = cached?.windows || await chrome.windows.getAll({ populate: true, windowTypes: ['normal'] });
            const tabGroups = await chrome.tabGroups?.query({}) || [];

            windows = windows.map(window => ({
                ...window,
                tabs: window.tabs?.filter(tab => tab?.url && !tab.pinned) || [],
                tabGroups: window.tabGroups
                    ? window.tabGroups.filter(group => group.windowId === window.id)
                    : tabGroups.filter(group => group.windowId === window.id)
            })).filter(window => window.tabs.length > 0);

            if (windows.length === 0) {
                throw new Error('No valid windows to snapshot');
            }

            const timestamp = cached?.createdAt || Date.now();
            const deviceName = cached?.deviceName;
            const summary = {
                id,
                deviceName: isAutoCreated ? "Auto" : deviceName,
                createdAt: timestamp,
                windowCount: cached?.windowCount || windows.length,
                tabCount: cached?.tabCount || windows.reduce((acc, window) => acc + window.tabs.length, 0),
                isAutoCreated,
            };
            const snapshot = { ...summary, windows };
            const oldSummaries = get().summaries;
            if (oldSummaries.length === 0) {
                await get().fetchSummaries();
            }

            let newSummaries = [...get().summaries, summary];
            const cacheInstance = await snapshotCacheInstance();

            set({ summaries: newSummaries });
            await cacheInstance.set(`snapshot_summary_${id}`, summary);
            await cacheInstance.set(`snapshot_detail_${id}`, snapshot);
        } catch (error) {
            console.error('Error adding snapshot:', error);
            throw error;
        }
    },

    removeSnapshot: async (id) => {
        if (!id) return;
        try {
            const cacheInstance = await snapshotCacheInstance();
            await Promise.all([
                cacheInstance.remove(`snapshot_summary_${id}`),
                cacheInstance.remove(`snapshot_detail_${id}`)
            ]);
            set({ summaries: get().summaries.filter(s => s?.id !== id) });
        } catch (error) {
            console.error('Error removing snapshot:', error);
            throw error;
        }
    },

    addImportedSnapshot: async (importedSnapshot) => {
        if (!importedSnapshot?.id || !importedSnapshot?.createdAt ||
            !importedSnapshot?.windowCount || !importedSnapshot?.tabCount ||
            !importedSnapshot?.windows) {
            throw new Error("Invalid snapshot data");
        }

        const { id, createdAt, windowCount, tabCount, windows, deviceName } = importedSnapshot;
        const summary = { id, createdAt, windowCount, tabCount, deviceName };
        const snapshot = { ...summary, windows };

        if (get().summaries.some(s => s?.id === id)) {
            throw new Error("Snapshot with the same ID already exists");
        }

        set({ summaries: [...get().summaries, summary] });

        const cacheInstance = await snapshotCacheInstance();
        await Promise.all([
            cacheInstance.set(`snapshot_summary_${id}`, summary),
            cacheInstance.set(`snapshot_detail_${id}`, snapshot)
        ]);
    },

    addSelectdTabId: (tabId, windowId) => {
        if (!tabId || !windowId) return;
        set(state => {
            const newSelectedTabs = { ...state.selectedTabs };
            if (!newSelectedTabs[windowId]) {
                newSelectedTabs[windowId] = [];
            }
            if (!newSelectedTabs[windowId].includes(tabId)) {
                newSelectedTabs[windowId].push(tabId);
            }
            return { selectedTabs: newSelectedTabs };
        });
    },

    removeSelectTabId: (tabId, windowId) => {
        if (!tabId || !windowId) return;
        set(state => {
            const newSelectedTabs = { ...state.selectedTabs };
            if (newSelectedTabs[windowId]) {
                newSelectedTabs[windowId] = newSelectedTabs[windowId].filter(id => id !== tabId);
            }
            return { selectedTabs: newSelectedTabs };
        });
    },

    addSelectdGroupId: (groupId, windowId) => {
        if (!groupId || !windowId) return;
        set(state => {
            const newSelectedGroups = { ...state.selectedGroups };
            if (!newSelectedGroups[windowId]) {
                newSelectedGroups[windowId] = [];
            }
            if (!newSelectedGroups[windowId].includes(groupId)) {
                newSelectedGroups[windowId].push(groupId);
            }
            return { selectedGroups: newSelectedGroups };
        });
    },

    removeSelectGroupId: (groupId, windowId) => {
        if (!groupId || !windowId) return;
        set(state => {
            const newSelectedGroups = { ...state.selectedGroups };
            if (newSelectedGroups[windowId]) {
                newSelectedGroups[windowId] = newSelectedGroups[windowId].filter(id => id !== groupId);
            }
            return { selectedGroups: newSelectedGroups };
        });
    },

    resetSelected: () => {
        set({ selectedTabs: {}, selectedGroups: {} });
    }

})), shallow));

const throttledAddCachedWindows = throttle(async () => {
    try {
        const [windows, tabGroups] = await Promise.all([
            chrome.windows.getAll({ populate: true }),
            chrome.tabGroups?.query({}) || []
        ]);

        const timestamp = Date.now();

        const filteredWindows = windows
            .map(window => ({
                ...window,
                tabs: window.tabs?.filter(tab => tab?.url && !tab.pinned) || [],
                tabGroups: tabGroups.filter(tabGroup => tabGroup.windowId === window.id)
            }))
            .filter(window => window.tabs.length > 0);

        const tabCount = filteredWindows.reduce((acc, window) => acc + window.tabs.length, 0);

        if (tabCount <= 3) return;

        const summary = {
            deviceName: "Last Closed",
            createdAt: timestamp,
            windowCount: filteredWindows.length,
            tabCount,
            tabGroupCount: tabGroups.length
        };

        const cacheInstance = await snapshotCacheInstance();
        await cacheInstance.set('cachedWindows', { ...summary, windows: filteredWindows });
    } catch (error) {
        console.error('Error adding cached windows:', error);
    }
}, 5000, { leading: true, trailing: true });

export const addCachedWindows = throttledAddCachedWindows;

export const getCachedWindows = async () => {
    try {
        const cacheInstance = await snapshotCacheInstance();
        return await cacheInstance.get('cachedWindows');
    } catch (error) {
        console.error('Error getting cached windows:', error);
        return null;
    }
};

export const removeCachedWindows = async () => {
    try {
        const cacheInstance = await snapshotCacheInstance();
        await cacheInstance.remove('cachedWindows');
    } catch (error) {
        console.error('Error removing cached windows:', error);
    }
};

export const getAllAutoSnapshotSummaries = async () => {
    const cacheInstance = await snapshotCacheInstance();
    const keys = await cacheInstance.keys();
    const summaries = await Promise.all(
        keys.filter(key => key.startsWith('snapshot_summary_'))
            .map(key => cacheInstance.get(key))
    );
    const filtered = summaries
        .filter(Boolean)
        .filter(summary => summary.isAutoCreated)
        .sort((a, b) => b.createdAt - a.createdAt);
    return filtered || [];
}

export const getLastAutoSnapshotSummary = async () => {
    const cacheInstance = await snapshotCacheInstance();
    const keys = await cacheInstance.keys();
    const summaries = await Promise.all(
        keys.filter(key => key.startsWith('snapshot_summary_'))
            .map(key => cacheInstance.get(key))
    );
    const filtered = summaries
        .filter(Boolean)
        .filter(summary => summary.isAutoCreated)
        .sort((a, b) => b.createdAt - a.createdAt);

    return filtered[0] || null;
}

export const addAutoSnapshot = async () => {
    try {
        recordDebugLog('Starting addAutoSnapshot');
        const cacheInstance = await snapshotCacheInstance();
        const maxAutoSnapshotCount = await getMaxAutoCreateSnapshotCount();
        recordDebugLog('Max auto snapshot count:', maxAutoSnapshotCount);

        // Get current windows and tab groups
        let windows = await chrome.windows.getAll({ populate: true, windowTypes: ['normal'] });
        const tabGroups = await chrome.tabGroups?.query({}) || [];
        recordDebugLog('Got windows and tab groups:', { windowCount: windows.length, tabGroupCount: tabGroups.length });

        // Process and filter windows 
        windows = windows.map(window => ({
            ...window,
            tabs: window.tabs?.filter(tab => tab?.url && !tab.pinned) || [],
            tabGroups: window.tabGroups
                ? window.tabGroups.filter(group => group.windowId === window.id)
                : tabGroups.filter(group => group.windowId === window.id)
        })).filter(window => window.tabs.length > 0);
        recordDebugLog('Processed windows:', { filteredWindowCount: windows.length });

        if (windows.length === 0) {
            recordDebugLog('No valid windows to snapshot');
            throw new Error('No valid windows to snapshot');
        }

        // Create summary object
        const summary = {
            id: uuidv4(),
            deviceName: "Auto",
            createdAt: Date.now(),
            windowCount: windows.length,
            tabCount: windows.reduce((acc, window) => acc + window.tabs.length, 0),
            isAutoCreated: true,
        };
        recordDebugLog('Created summary:', summary);

        // Check if identical to last auto snapshot
        const lastAutoSnapshotSummary = await getLastAutoSnapshotSummary();
        recordDebugLog('Got last auto snapshot summary:', lastAutoSnapshotSummary?.id);
        if (lastAutoSnapshotSummary?.id) {
            const lastAutoSnapshot = await cacheInstance.get(`snapshot_detail_${lastAutoSnapshotSummary.id}`);
            if (lastAutoSnapshot?.windows && compareWindows(windows, lastAutoSnapshot.windows)) {
                recordDebugLog('Windows identical to last auto snapshot, updating timestamp');
                const updatedSummary = {
                    ...summary,
                    id: lastAutoSnapshot.id
                };
                const updatedSnapshot = {
                    ...updatedSummary,
                    windows
                };
                await Promise.all([
                    cacheInstance.set(`snapshot_summary_${lastAutoSnapshot.id}`, updatedSummary),
                    cacheInstance.set(`snapshot_detail_${lastAutoSnapshot.id}`, updatedSnapshot)
                ]);
                recordDebugLog('Updated existing snapshot');
                return;
            }
        }

        // Manage auto snapshot count
        const allAutoSnapshotSummaries = await getAllAutoSnapshotSummaries();
        recordDebugLog('Current auto snapshot count:', allAutoSnapshotSummaries.length);
        if (allAutoSnapshotSummaries.length >= maxAutoSnapshotCount) {
            const toRemoveSnapshots = allAutoSnapshotSummaries.slice(maxAutoSnapshotCount - 1);
            recordDebugLog('Removing old snapshots:', toRemoveSnapshots.length);
            await Promise.all(
                toRemoveSnapshots.flatMap(snapshot => snapshot?.id ? [
                    cacheInstance.remove(`snapshot_summary_${snapshot.id}`),
                    cacheInstance.remove(`snapshot_detail_${snapshot.id}`)
                ] : [])
            );
        }

        // Save new snapshot
        const snapshot = { ...summary, windows };
        recordDebugLog('Saving new snapshot:', summary.id);
        await Promise.all([
            cacheInstance.set(`snapshot_summary_${summary.id}`, summary),
            cacheInstance.set(`snapshot_detail_${summary.id}`, snapshot)
        ]);
        recordDebugLog('Successfully saved new auto snapshot');
    } catch (error) {
        console.error('Error adding auto snapshot:', error);
        throw error;
    }
}

export default snapshotStore;