import React, { memo, forwardRef } from "react";
import { useTranslationContext } from "../../Providers/TranslationProvider";
import userStore from "../../../core/stores/userStore";
import tabStore from "../../../core/stores/tabStore";
import { Stack } from "@mui/material";
import TabAdd from "../../component/TabAdd";
import TabFocus from "../tabs/tab/TabFocus";
import TabGoBack from "../tabs/tab/TabGoBack";
import TabGoForward from "../tabs/tab/TabGoForward";
import TabsMute from "../../component/TabsMute";
import ExpandedSwitch from "../../component/ExpandedSwitch";
import TabGroupBy from "../../component/TabGroupBy";
import TabOrderBy from "../../component/TabOrderBy";
import ThemeSwitch from "../../component/ThemeSwitch";
import ViewSwitch from "../../component/ViewSwitch";
import ClearTabs from "../tabs/ClearTabs";
import TabRefresh from "../tabs/tab/TabRefresh";
import BookmarksHeader from "../bookmarks/BookmarksHeader";
import TabEnterPip from "../tabs/tab/TabEnterPip";
import CreateSnapshotIconBtn from "../tabs/tab/CreateSnapshotIconBtn";


const Toolbar = forwardRef((props, ref) => {
    const { t } = useTranslationContext();

    const { showToolbar, activeTabIndex, toolbarOptions } = userStore((state) => state.settings);

    const { soundTabsCount, isActiveTabIntersecting, activeTabId } = tabStore((state) => ({
        soundTabsCount: state.tabs.reduce((count, tab) => tab.audible && !tab.mutedInfo.muted ? count + 1 : count, 0),
        isActiveTabIntersecting: state.isActiveTabIntersecting,
        activeTabId: state.activeTabId,
    }));

    if (!showToolbar) {
        return null;
    }

    const leftNavs = toolbarOptions.navs
        .filter(nav => nav.enable && nav.align === "flex-start")
        .sort((a, b) => a.sort - b.sort);
    const rightNavs = toolbarOptions.navs
        .filter(nav => nav.enable && nav.align === "flex-end")
        .sort((a, b) => a.sort - b.sort);

    const renderNav = (nav) => {
        switch (nav.name) {
            case "newTab": return <TabAdd key='toolbar-tab-add' showText={toolbarOptions.showLabel} />;
            case "tabGoBack": return <TabGoBack key='toolbar-tab-go-back' tabId={activeTabId} showText={toolbarOptions.showLabel} />;
            case "tabGoForward": return <TabGoForward key='toolbar-tab-go-forward' tabId={activeTabId} showText={toolbarOptions.showLabel} />;
            case "tabRefresh": return <TabRefresh key='toolbar-tab-refresh' tabId={activeTabId} showText={toolbarOptions.showLabel} />;
            case "scrollToActiveTab": return !isActiveTabIntersecting && <TabFocus key='toolbar-tab-focus' label={t("ScrollToActiveTab")} />;
            case "muteAllTabs": return soundTabsCount > 0 && <TabsMute key='toolbar-tabs-mute' />;
            case "collapseAll": return <ExpandedSwitch key='toolbar-expanded-switch' sx={{ flexShrink: 0 }} />;
            case "createSnapshot": return <CreateSnapshotIconBtn key='toolbar-create-snapshot' showText={toolbarOptions.showLabel} />;
            case "switchPIP": return <TabEnterPip key='toolbar-tab-enter-pip' tabId={activeTabId} showText={toolbarOptions.showLabel} />;
            case "showBy": return <TabGroupBy key='toolbar-tab-group-by' showText={toolbarOptions.showLabel} />;
            case "sortBy": return <TabOrderBy key='toolbar-tab-order-by' showText={toolbarOptions.showLabel} />;
            case "themeModes": return <ThemeSwitch key='toolbar-theme-switch' />;
            case "viewModes": return <ViewSwitch key='toolbar-view-switch' />;
            case "clearTabs": return <ClearTabs key='toolbar-clear-tabs' showText={toolbarOptions.showLabel} />;
            default: return null;
        }
    };

    return (
        <Stack ref={ref} direction="row" justifyContent="space-between" alignItems="center">
            {activeTabIndex === 2 ? (
                <BookmarksHeader showBack={false} />
            ) : (
                <>
                    <Stack direction="row" alignItems="center" spacing={0}>
                        {leftNavs.map(nav => renderNav(nav))}
                    </Stack>
                    <Stack direction="row" alignItems="center" spacing={0}>
                        {rightNavs.map(nav => renderNav(nav))}
                    </Stack>
                </>
            )}
        </Stack>
    );
});

export default memo(Toolbar);