import { getDomainFromUrl } from "../../utils/helpers";
import { getActiveTab } from "./tabs";

export const getActivedTabCookies = async () => {
    if (!chrome.cookies) {
        console.error("chrome.cookies is not available");
        return [];
    }

    try {
        const currentTab = await getActiveTab();
        if (!currentTab) return [];
        return await getTabCookies(currentTab.id);
    } catch (error) {
        console.error("Error in getActivedTabCookies:", error);
        return [];
    }
}

export async function getTabCookies(tabId) {
    if (!chrome.cookies) {
        console.error("chrome.cookies is not available");
        return [];
    }

    try {
        if (!tabId || tabId <= 0) return [];

        const tab = await chrome.tabs.get(tabId);
        const domain = getDomainFromUrl(tab.url || tab.pendingUrl);
        return await chrome.cookies.getAll({ domain });
    } catch (error) {
        console.error("Error in getTabCookies:", error);
        return [];
    }
}

export const getTabCookieStrings = async (tabId) => {
    if (!chrome.cookies) {
        console.error("chrome.cookies is not available");
        return '';
    }

    try {
        const cookies = await getTabCookies(tabId);
        const currentTime = Math.floor(Date.now() / 1000);

        return cookies
            .filter(cookie => cookie.session || cookie.expirationDate >= currentTime)
            .map(cookie => `${cookie.name}=${cookie.value};`)
            .join('');
    } catch (error) {
        console.error("Error in getTabCookieStrings:", error);
        return '';
    }
}

export const formatCookieString = (setCookieString, url) => {
    try {
        const cookieParts = setCookieString.split(';').map(part => part.trim());
        const [cookieName, ...valueParts] = cookieParts[0].split('=');
        const cookieValue = valueParts.join('=') || '';

        const cookieAttributes = cookieParts.slice(1).reduce((attrs, part) => {
            const [attrKey, ...attrValueParts] = part.split('=');
            attrs[attrKey.toLowerCase()] = attrValueParts.length ? attrValueParts.join('=') : true;
            return attrs;
        }, {});

        const formattedCookie = {
            name: cookieName,
            value: cookieValue,
            domain: cookieAttributes.domain || '.' + getDomainFromUrl(url),
            path: cookieAttributes.path || '/',
            secure: 'secure' in cookieAttributes,
            httpOnly: 'httponly' in cookieAttributes,
            sameSite: cookieAttributes.samesite || 'no_restriction',
            session: !cookieAttributes.expires
        };

        if (cookieAttributes.expires) {
            formattedCookie.expirationDate = new Date(cookieAttributes.expires).getTime() / 1000;
        }

        return formattedCookie;
    } catch (error) {
        console.error("Error in formatCookieString:", error);
        return null;
    }
}

export const clearCookiesfromUrl = async (url, skipAccountCookies = false) => {
    if (!chrome.cookies) {
        console.error("chrome.cookies is not available");
        return false;
    }

    try {
        const cookies = await chrome.cookies.getAll({ url });

        const promises = cookies.map(async (cookie) => {
            if (skipAccountCookies && /account|auth|login/i.test(url)) {
                return;
            }

            try {
                await chrome.cookies.remove({ url, name: cookie.name });
            } catch (error) {
                console.error(`Error removing cookie ${cookie.name}:`, error);
            }
        });

        await Promise.all(promises);
        return true;
    } catch (error) {
        console.error("Error in clearCookiesfromUrl:", error);
        return false;
    }
}
