let currentWindow = null;

export const getCurrentWindow = async () => {
    // Return cached window if available
    if (currentWindow) {
        try {
            // Verify cached window still exists
            await chrome.windows.get(currentWindow.id);
            return currentWindow;
        } catch {
            // Clear cache if window no longer exists
            currentWindow = null;
        }
    }

    try {
        currentWindow = await chrome.windows.getCurrent();
        return currentWindow;
    } catch (error) {
        console.error("Failed to get current window:", error);
        return null;
    }
};