import React from "react";
import { MenuItem, ListItemText, Typography, ListItemIcon, Stack } from "@mui/material";
import { AddtoReadinglist, isSupportReadingList } from "../../../../core/browers/readingList";
import tabStore from "../../../../core/stores/tabStore";
import { toast } from "react-toastify";
import { PostAdd } from "@mui/icons-material";
import userStore from "../../../../core/stores/userStore";
import { useTranslationContext } from "../../../Providers/TranslationProvider";
import PermissionRequireIcon from "../../../component/PermissionRequireIcon";
import { useState } from "react";
import { useEffect } from "react";

export default function AddToReadingList({ tabId, onSelect }) {
    const { t } = useTranslationContext();
    const theme = userStore(state => state.settings.theme);

    const tab = tabStore(state => {
        const { title, url } = state.tabs.find(t => t.id === tabId) || {};
        return { title, url };
    });

    const [permission, setPermission] = useState(false);
    useEffect(() => {
        const checkPermission = async () => {
            const result = await chrome.permissions.contains({ permissions: ['readingList'] });
            setPermission(result);
        };
        checkPermission()
    }, [permission]);

    const handleClick = async () => {

        if (!permission) {
            toast.error(t('featureRequiresPermission', { permission: "readingList" }));
            return;
        }

        await AddtoReadinglist(tab);
        toast.success(t("AddedToReadingListSuccessfully"), {
            position: "bottom-center",
            hideProgressBar: true,
            theme: theme,
            autoClose: 1500
        });
        if (typeof onSelect === 'function') {
            onSelect();
        }
    };

    if (navigator.userAgent.includes("OPR")) {
        return null;
    }

    return (

        <MenuItem onClick={handleClick}>
            <ListItemIcon>
                <PostAdd />
            </ListItemIcon>
            <ListItemText>
                <Stack direction="row" alignItems="center" justifyContent="space-between">
                    <Typography variant="body1">{t("tabMenu.AddToReadingList")}</Typography>
                    <PermissionRequireIcon permissionName={"readingList"} />
                </Stack>

            </ListItemText>
        </MenuItem>

    );
}