import React, { memo } from "react";
import { ListItemButton, Box, Stack, Typography } from "@mui/material";
import { useSettingsContext } from "../../../Providers/SettingsProvider";
import { UnfoldMore } from "@mui/icons-material";

export default memo(function TabHistoryItemMore({ handleLoadMore }) {
  const { theme, fontColor, buttonPosition } = useSettingsContext();

  return (
    <Box
      sx={{
        position: "relative",
        paddingInlineStart: '18px',
        '&:before': {
          borderLeft: `1px solid ${theme === "dark" ? "#fff" : (fontColor === 'inherit' || !fontColor) ? "#ccc" : fontColor}`,
          content: '""',
          height: '100%',
          left: buttonPosition === 'row' ? '18px' : 'auto',
          right: buttonPosition !== 'row' ? '18px' : 'auto',
          position: 'absolute',
          top: '-10px',
        },
        '&:after': {
          borderTop: `1px solid ${theme === "dark" ? "#fff" : (fontColor === 'inherit' || !fontColor) ? "#ccc" : fontColor}`,
          content: '""',
          position: 'absolute',
          top: '9px',
          left: buttonPosition === 'row' ? '18px' : 'auto',
          right: buttonPosition !== 'row' ? '18px' : 'auto',
          width: '12px',
          zIndex: 999
        },
      }}
    >
      <ListItemButton
        onClick={handleLoadMore}
        dense
        disableGutters
        sx={{
          width: "100%",
          ...(buttonPosition === "row" ? { paddingRight: "0px", paddingLeft: "12px" } : { paddingLeft: "0px", paddingRight: "25px" }),
          paddingY: "2px",
          "&:hover": {
            background: theme === "dark" ? "rgba(255, 255, 255, 0.1)" : "rgba(0, 0, 0, 0.1)",
            backdropFilter: "blur(5px)",
          },
        }}
      >
        <Stack direction={buttonPosition} alignItems="center" spacing={1} sx={{ width: "100%" }}>
          <UnfoldMore sx={{ fontSize: '12px', opacity: 0.7 }} />
          <Typography
            variant="body2"
            sx={{
              opacity: 0.7,
              whiteSpace: "nowrap",
              overflow: "hidden",
              textOverflow: "ellipsis"
            }}
          >
            ++++++
          </Typography>
        </Stack>
      </ListItemButton>
    </Box>
  );
});